import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"评估与成本","description":"Hearth 如何用真实任务、验证器、基线和成本指标证明能力，而不是用演示证明能力。","frontmatter":{"title":"评估与成本","description":"Hearth 如何用真实任务、验证器、基线和成本指标证明能力，而不是用演示证明能力。","outline":false},"headers":[],"relativePath":"design/evaluation.md","filePath":"design/evaluation.md","lastUpdated":1793863446000}'),o={name:"design/evaluation.md"};function n(p,t,i,l,s,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="评估与成本" tabindex="-1">评估与成本 <a class="header-anchor" href="#评估与成本" aria-label="Permalink to &quot;评估与成本&quot;">​</a></h1><p class="lead">演示不是能力。Hearth 只相信可重复、可验证、包含失败样本的证据；评估不仅要看任务是否完成，还要看人工时间、打断次数、恢复能力、外部副作用和成本。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>评估要覆盖真实任务，而不是只测顺利路径。任务集应包含正常、边界、失败和恶意输入，并且保留一部分不参与调参的保留集。失败样本不能因为不好看就被删除，新增能力也不能只增加一个演示。</p><p>完成标准由验证器决定，而不是模型自评。代码看测试和差异，文档看结构与引用，邮件看收件人、事实和发送回执，网页看最终状态和可访问性，桌面操作看目标状态，数据看结构、行数、抽样和对账。无法自动验证的结果需要明确的人工验收。</p><p>评估要能比较替代方案。至少比较全人工、直接使用通用编码代理、当前 Hearth 和替代路由或方法版本，观察成功率、人工分钟、打断、延迟、成本和恢复，而不是只比较输出文字是否看起来更好。</p><p>成本要和有效完成绑定。目标不是单纯少用 Token，而是每次有效完成更省。Token、金额、延迟、工具调用、网络请求和人工打断都属于预算；任何一级耗尽都应暂停、降级或转人工，不能静默透支。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>测试和评估分开。测试是确定性的通过或失败门槛，适合每次提交运行；评估是带统计性质的质量测量，需要任务集、基线和多次比较。两者都重要，但不能混成一个只看平均分的 CI 门槛。</p><table tabindex="0"><thead><tr><th>评估层级</th><th>观察什么</th><th>使用时机</th></tr></thead><tbody><tr><td>组件测试</td><td>解析、连接器、策略、验证器和恢复逻辑</td><td>每次提交</td></tr><tr><td>单任务端到端</td><td>一个真实任务是否完成、是否有证据</td><td>每次发布</td></tr><tr><td>轨迹重放</td><td>历史过程换路由、换模型或注入故障后是否仍可靠</td><td>持续</td></tr><tr><td>无副作用试跑</td><td>真实输入但不产生外部影响</td><td>能力变更前</td></tr><tr><td>小范围真实使用</td><td>真实用户、真实动作、受控范围</td><td>阶段推进前</td></tr><tr><td>长期运行</td><td>多设备、离线、升级、记忆变化和资源稳定性</td><td>阶段验收与 v1.0</td></tr></tbody></table><p>初始任务集建议覆盖 40 到 60 个真实任务，包含邮件、日历、文档、调研、代码、网页、桌面和跨应用流程。真实脱敏数据优先，合成数据要标记；任务目标、输入、验收方式和验证器都必须明确。</p><p>核心指标包括：通过验证器的任务比例、每有效完成的人工分钟、每任务打断次数、崩溃或断网后的恢复比例、故障注入下的重复副作用、未授权高风险动作、每有效完成的 Token 与综合成本、记忆召回准确率，以及方法升级导致的旧任务回归。</p><p>验证器优先确定性结果。能检查文件和差异就不看模型解释，能查询外部系统状态就不相信自然语言“已发送”，能对账就不只看返回成功。对无法完全自动验证的任务，保留人工验收记录和抽样复核。</p><p>故障注入是评估的一部分。至少覆盖进程崩溃、网络中断、超时、重复投递、磁盘不足、外部服务限流或认证过期、设备离线、审批过期和缓存失效。系统在这些情况下不一定成功，但必须诚实失败、可恢复且不重复产生副作用。</p><p>成本控制按“规则优先、结构化优先、引用优先、小模型优先、缓存优先、停止优先”的原则组织。上下文只放本次任务需要的证据，长材料先索引和检索，重复内容使用缓存，但缓存必须有版本和删除规则，不能复活已遗忘内容。</p><p>评估结果要进入发布门槛，而不是放在附录。第一阶段要证明最小产品可每天使用、可恢复、可审批且没有重复副作用；后续阶段每增加一种能力，就同步扩大对应的真实任务、安全测试和成本观察。平均值不能掩盖某个任务族全面失败。</p>',16)])])}const u=a(o,[["render",n]]);export{_ as __pageData,u as default};
